-- ============================================================================
-- Migration 0002: allow decimal duration_minutes (hours:minutes:seconds picker)
--
-- Changes the services.duration_minutes column from integer to numeric(8,4)
-- so it can store values like 30.5 (= 30 min 30 sec).
-- Also raises the upper-bound CHECK to 1440 (24 hours).
--
-- Run in Supabase SQL Editor after 0001_initial_schema.sql.
-- ============================================================================

-- Step 1: drop the old integer check constraint (name auto-generated by Postgres).
alter table public.services
  drop constraint if exists services_duration_minutes_check;

-- Step 2: change the column type to numeric with 4 decimal places.
alter table public.services
  alter column duration_minutes type numeric(8,4)
  using duration_minutes::numeric(8,4);

-- Step 3: add the new check that allows decimals and raises the max to 1440.
alter table public.services
  add constraint services_duration_minutes_check
  check (duration_minutes > 0 and duration_minutes <= 1440);
